arguments.command:
python - <<'PY'
import sys, subprocess
mods=['pandas','openpyxl','docx']
missing=[]
for m in mods:
    try:
        __import__(m)
    except ImportError:
        missing.append('python-docx' if m=='docx' else m)
if missing:
    print('Installing missing:', missing)
    subprocess.check_call([sys.executable,'-m','pip','install',*missing])
else:
    print('All required packages available')
PY
